// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Consumable) predicate.Consumable {
	return predicate.Consumable(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Consumable) predicate.Consumable {
	return predicate.Consumable(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Consumable) predicate.Consumable {
	return predicate.Consumable(sql.NotPredicates(p))
}
